def expand(text, scope, local_vars=None):
    if not text: return ""
    result = []
    i = 0
    while i < len(text):
        if text[i] == '$':
            i += 1
            if i >= len(text): break
            if text[i] == '$':
                result.append('$')
                i += 1
            elif text[i] == ' ':
                result.append(' ')
                i += 1
            elif text[i] == '\n':
                i += 1
                while i < len(text) and text[i] in ' \t':
                    i += 1
            elif text[i] == '{':
                i += 1
                start = i
                while i < len(text) and text[i] != '}':
                    i += 1
                var_name = text[start:i]
                i += 1
                val = ""
                if local_vars and var_name in local_vars:
                    val = local_vars[var_name]
                else:
                    val = scope.get_var(var_name)
                result.append(val)
            else:
                start = i
                while i < len(text) and (text[i].isalnum() or text[i] in '_-'):
                    i += 1
                var_name = text[start:i]
                val = ""
                if local_vars and var_name in local_vars:
                    val = local_vars[var_name]
                else:
                    val = scope.get_var(var_name)
                result.append(val)
        else:
            result.append(text[i])
            i += 1
    return "".join(result)

