        if self.rule:
            if self.rule.name == 'phony':
                self.command = ""
                self.description = ""
            else:
                self.command = expand(self.rule.vars.get('command', ''), self.scope, local_vars)
                self.description = expand(self.rule.vars.get('description', ''), self.scope, local_vars)
